1	import type { HarnessPreflight, HarnessReadinessState } from '@graphgoblin/contracts';
2	
3	/** The no-turn readiness check does not establish loaded plugin/tool health. */
4	export const CODEX_PLUGIN_OBSERVABILITY_NOTICE =
5	  'Loaded plugin tools are not verified by this check. Inspect codex plugin list --json and codex mcp list --json in the worker directory; neither proves every enabled plugin loaded. Verify the expected tool in the worker before relying on it.';
6	
7	/** Classify bounded CLI diagnostics ephemerally; never return executable output to a client. */
8	export function cliFailureState(text: string): HarnessReadinessState {
9	  // Version components and arbitrary numbers are not HTTP status evidence.
10	  const match =
11	    /\bHTTP(?:\/[\d.]+)?\s+([45]\d\d)\b|\bstatus(?:_code)?["']?\s*[:=]\s*([45]\d\d)\b|\bAPI Error:\s*([45]\d\d)\b/i.exec(
12	      text,
13	    );
14	  const status = Number(match?.[1] ?? match?.[2] ?? match?.[3]);
15	  if (
16	    /unknown (option|argument)|unexpected argument|unrecognized (option|argument)|unsupported (option|flag)/i.test(
17	      text,
18	    )
19	  )
20	    return 'cli-incompatible';
21	  // A returned HTTP/API status is stronger evidence than incidental diagnostic wording.
22	  if (status === 401 || status === 403) return 'auth';
23	  if (status === 429) return 'quota';
24	  if (status >= 500 && status <= 599) return 'transport';
25	  // Connection evidence takes precedence over auth words in server/refresh diagnostics.
26	  if (
27	    /\beconn\w*\b|\benotfound\b|\betimedout\b|\beai_again\b|network|failed to connect|connection failed|stream disconnected|overloaded|temporarily unavailable/i.test(
28	      text,
29	    )
30	  )
31	    return 'transport';
32	  if (/quota|usage[_ ]limit|rate[_ ]limit|too many requests/i.test(text)) return 'quota';
33	  if (
34	    /not logged in|unauthori[sz]ed|authentication|authenticat|login required|token (has )?expired|invalid api key|please run \/login/i.test(
35	      text,
36	    )
37	  )
38	    return 'auth';
39	  return 'unknown';
40	}
41	
42	/** The product name in user-facing text: `Claude`, `Codex`, otherwise the capitalised id. */
43	export function harnessDisplayName(harness: string): string {
44	  if (harness === 'claude') return 'Claude';
45	  if (harness === 'codex') return 'Codex';
46	  return harness.charAt(0).toUpperCase() + harness.slice(1);
47	}
48	
49	/** One sentence saying what the no-turn check found, used when no more specific detail is known. */
50	export function readinessDetail(harness: string, state: HarnessReadinessState): string {
51	  const name = harnessDisplayName(harness);
52	  if (harness === 'ollama') {
53	    if (state === 'ready')
54	      return 'Ollama service metadata probe passed; model execution and memory requirements are not tested.';
55	    if (state === 'auth') return 'Ollama service rejected access.';
56	    if (state === 'quota') return 'Ollama service usage limit reached.';
57	    if (state === 'transport') return 'Ollama service is unavailable.';
58	    return 'Ollama service readiness could not be confirmed.';
59	  }
60	  switch (state) {
61	    case 'ready':
62	      return `${name} CLI version, required options and sign-in passed; account model access is not tested.`;
63	    case 'cli-missing':
64	      return `${name} CLI was not found.`;
65	    case 'cli-incompatible':
66	      return `${name} CLI lacks a required capability.`;
67	    case 'auth':
68	      return `${name} sign-in is missing or invalid.`;
69	    case 'quota':
70	      return `${name} account usage limit reached.`;
71	    case 'transport':
72	      return `${name} reported a connection or provider service error.`;
73	    case 'unknown':
74	      return `${name} readiness could not be confirmed.`;
75	  }
76	}
77	
78	/** The one next step for a failed state; each ends with retrying preflight, the check that clears it. */
79	export function readinessAction(
80	  harness: string,
81	  state: Exclude<HarnessReadinessState, 'ready'>,
82	): string {
83	  const name = harnessDisplayName(harness);
84	  if (harness === 'ollama') {
85	    if (state === 'auth')
86	      return 'Configure service access outside GraphGoblin, then retry preflight.';
87	    if (state === 'quota')
88	      return 'Wait for the service usage limit to reset, then retry preflight.';
89	    return 'Check the Ollama connection URL and service, then retry preflight.';
90	  }
91	  switch (state) {
92	    case 'cli-missing':
93	      return `Install the ${name} CLI or set ${harness === 'claude' || harness === 'codex' ? `GG_${harness.toUpperCase()}_BINARY` : 'its binary path'}, then retry preflight.`;
94	    case 'cli-incompatible':
95	      return `Update the ${name} CLI, then retry preflight.`;
96	    case 'auth':
97	      return `Run ${harness === 'claude' ? 'claude auth login' : harness === 'codex' ? 'codex login' : `the ${name} login command`}, then retry preflight.`;
98	    case 'quota':
99	      return 'Wait for the usage limit to reset, then retry preflight.';
100	    case 'transport':
101	      return "Check the network connection and the provider's service status, then retry preflight.";
102	    case 'unknown':
103	      return `Check that the ${name} CLI starts and responds, then retry preflight.`;
104	  }
105	}
