142	    this.preflightResult = readyClaudePreflight;
143	  }
144	
145	  override start(request: HarnessStartRequest, signal: AbortSignal): HarnessSession {
146	    if (this.termination === 'confirmed') return super.start(request, signal);
147	    this.started.push(request);
148	    this.terminationSession += 1;
149	    const sessionId = 'fake-claude-unconfirmed-' + this.terminationSession;
150	    const error = Object.assign(
151	      new Error('Termination not confirmed; stop the E2E fake before retrying.'),
152	      { code: 'HARNESS_TERMINATION_UNCONFIRMED', retriable: false },
153	    );
154	    const result: HarnessSession['result'] = new Promise((_, reject) => {
155	      if (signal.aborted) reject(error);
156	      else signal.addEventListener('abort', () => reject(error), { once: true });
157	    });
158	    result.catch(() => undefined);
159	    const events = async function* (): AsyncGenerator<HarnessEvent> {
160	      yield { type: 'session', sessionId, mode: 'fresh' };
161	      await result.catch(() => undefined);
162	      yield {
163	        type: 'error',
164	        code: error.code,
165	        message: error.message,
166	        retriable: false,
167	        submission: 'delivery-uncertain',
168	      };
169	    };
170	    return {
171	      sessionId: Promise.resolve(sessionId),
172	      events: events(),
173	      result,
174	      cancel: () => Promise.reject(error),
175	    };
176	  }
177	}
178	
179	async function startApp(
180	  env: Record<string, string> = {},
181	  requireApiKey = false,
182	  realClassifiers = false,
183	  options: { claude?: boolean; id?: string; tempPrefix?: string } = {},
184	) {
185	  const id = options.id ?? 'e2e-instance-' + nextInstanceId++;
186	  const codex = new FakeHarness([], 'codex');
187	  const claude = options.claude ? new E2eClaudeHarness() : undefined;
188	  const harnesses = { codex, ...(claude ? { claude } : {}) };
189	  const storage = { availableBytes: 50 * 1024 ** 3 };
190	  const app = await createTestApp({
191	    storageCapacity: {
192	      read: () =>
193	        Promise.resolve({ totalBytes: 100 * 1024 ** 3, availableBytes: storage.availableBytes }),
194	    },
195	    ...(options.tempPrefix ? { tempPrefix: options.tempPrefix } : {}),
196	    env: { GG_WEB_DIST: dist, ...env },
197	    requireApiKey,
198	    realClassifiers,
199	    harnesses,
200	  });
201	  apps.push(app);
202	  const url = await app.app.listen({
203	    host: '127.0.0.1',
204	    port: id === 'main' ? Number(process.env['GG_E2E_MAIN_PORT'] ?? 0) : 0,
205	  });
206	  const instance: E2eInstance = { id, app, url, harnesses };
207	  storageCapacities.set(id, storage);
208	  instances.set(id, instance);
209	  return instance;
210	}
211	
212	const main = await startApp({}, false, false, { id: 'main' });
213	const workerPath = join(dist, 'sw.js');
214	// A stopped legacy-fallback test can leave its marked omission in the disposable build. Recover
215	// the exact original import expression before taking the baseline, just as build markers recover.
216	const originalWorker = cleanWorker(await readFile(workerPath, 'utf8')).replace(
217	  /\/\* E2E legacy guard: (importScripts\(\s*(["'])chat-update-worker\.js\2\s*\)) \*\/void 0/g,
218	  '$1',
219	);
220	const guardImport = /\bimportScripts\(\s*(["'])chat-update-worker\.js\1\s*\)/;
221	if (!guardImport.test(originalWorker) || !existsSync(join(dist, 'chat-update-worker.js')))
222	  throw new Error(
223	    'E2E PWA checks require the current built worker and chat-update-worker.js. Rebuild the web app.',
224	  );
225	// Keep the real precache/navigation worker. Omitting its helper models an active pre-guard build
226	// with no capability response; the reversible marker also preserves interrupted-run recovery.
227	const legacyWorker = originalWorker.replace(
228	  guardImport,
229	  (statement) => `/* E2E legacy guard: ${statement} */void 0`,
230	);
231	let workerBuild = 0;
232	
233	/** Drop real HTTP connections, then reuse the same listener and in-memory API state. */
234	async function setApiListening(instance: E2eInstance, listening: boolean): Promise<void> {
235	  const server = instance.app.app.server;
236	  if (listening === server.listening) return;
237	  if (listening) {
238	    await new Promise<void>((done, reject) => {
239	      server.once('error', reject);
240	      server.listen(Number(new URL(instance.url).port), '127.0.0.1', () => {
241	        server.removeListener('error', reject);
242	        done();
243	      });
244	    });
245	  } else {
246	    await new Promise<void>((done, reject) => {
247	      server.close((error) => (error ? reject(error) : done()));
248	      server.closeAllConnections();
249	    });
250	  }
251	}
252	
253	/** A scripted turn as JSON: `items` may be a count of generated progress items. */
254	interface TurnSpec {
255	  matchPrompt?: string;
256	  items?: number | ScriptedTurn['items'];
257	  finalText?: string;
258	  structured?: unknown;
259	  error?: ScriptedTurn['error'];
260	  delayMs?: number;
261	}
262	
263	function toTurn(spec: TurnSpec): ScriptedTurn {
264	  const { matchPrompt, items, error, ...rest } = spec;
265	  return {
266	    ...rest,
267	    ...(error ? { error } : {}),
268	    ...(matchPrompt ? { match: (request) => request.prompt.includes(matchPrompt) } : {}),
269	    ...(typeof items === 'number'
270	      ? {
271	          items: Array.from({ length: items }, (_, i) => ({
272	            id: `item-${i + 1}`,
273	            type: 'message' as const,
274	            summary: `streamed item ${i + 1}`,
275	          })),
276	        }
277	      : items
278	        ? { items }
279	        : {}),
280	  };
281	}
282	
283	async function readJson(request: IncomingMessage): Promise<Record<string, unknown>> {
284	  let body = '';
285	  for await (const chunk of request) body += String(chunk);
286	  return body ? (JSON.parse(body) as Record<string, unknown>) : {};
287	}
288	
289	function selectedInstance(body: Record<string, unknown>): E2eInstance {
290	  const id = typeof body['instanceId'] === 'string' ? body['instanceId'] : 'main';
291	  const instance = instances.get(id);
292	  if (!instance) throw new E2eControlError("unknown E2E instance '" + id + "'");
293	  return instance;
294	}
295	
296	function selectedHarness(
297	  instance: E2eInstance,
298	  body: Record<string, unknown>,
299	): { harness: 'codex' | 'claude'; fake: FakeHarness } {
300	  const requested = body['harness'] === undefined ? 'codex' : body['harness'];
301	  if (requested !== 'codex' && requested !== 'claude') {
302	    const label = typeof requested === 'string' ? requested : typeof requested;
303	    throw new E2eControlError("unknown E2E harness '" + label + "'");
304	  }
305	  const fake = instance.harnesses[requested];
306	  if (!fake)
307	    throw new E2eControlError(
308	      "harness '" + requested + "' is not enabled for E2E instance '" + instance.id + "'",
309	    );
310	  return { harness: requested, fake };
311	}
312	
313	async function control(request: IncomingMessage, response: ServerResponse): Promise<unknown> {
314	  const body = await readJson(request);
315	  const target = main.app;
316	  switch (request.url) {
317	    case '/voice/public-sample':
318	      // Public fixture bytes for Chromium's fake device, never ambient microphone input.
319	      return { wavBase64: voiceProbeSample().toString('base64') };
320	    case '/storage/capacity': {
321	      const instance = selectedInstance(body);
322	      storageCapacities.get(instance.id)!.availableBytes = z
323	        .number()
324	        .int()
325	        .nonnegative()
326	        .parse(body['availableBytes']);
327	      instance.app.clock.advance(60_000);
328	      await instance.app.container.historyCleanup.poll();
329	      return instance.app.container.historyCleanup.status();
330	    }
331	    case '/clock/advance':
332	      selectedInstance(body).app.clock.advance(
333	        z.number().int().positive().parse(body['milliseconds']),
334	      );
335	      return { ok: true };
336	    case '/api/listener':
337	      await setApiListening(selectedInstance(body), body['listening'] !== false);
338	      return { ok: true };
339	    case '/worker/build': {
340	      const mode = z.enum(['guarded', 'legacy']).parse(body['mode'] ?? 'guarded');
341	      workerBuild += 1;
342	      await writeFile(
343	        workerPath,
344	        `${mode === 'legacy' ? legacyWorker : originalWorker}\n// E2E build ${workerBuild}\n`,
345	      );
346	      return { build: workerBuild, mode };
347	    }
348	    case '/worker/reset':
349	      await writeFile(workerPath, originalWorker);
350	      return { ok: true };
351	    case '/harness/script':
352	      selectedHarness(selectedInstance(body), body).fake.script(
353	        ((body['turns'] as TurnSpec[] | undefined) ?? []).map(toTurn),
354	      );
355	      return { ok: true };
356	    case '/harness/requests': {
357	      const instance = selectedInstance(body);
358	      const { harness, fake } = selectedHarness(instance, body);
359	      const detailed = body['instanceId'] !== undefined || body['harness'] !== undefined;
360	      return {
361	        started: fake.started.map((r) => ({
362	          model: r.model,
363	          effort: r.effort,
364	          ...(detailed ? { harness, options: r.options } : {}),
365	        })),
366	      };
367	    }
368	    case '/harness/preflight': {
369	      const instance = selectedInstance(body);
370	      const { harness, fake } = selectedHarness(instance, body);
371	      if (harness !== 'claude' || !(fake instanceof E2eClaudeHarness))
372	        throw new E2eControlError('preflight controls are available only for the Claude E2E fake');
373	      if (body['state'] === 'ready')
374	        fake.preflightResult = HarnessPreflightSchema.parse({
375	          ...readyClaudePreflight,
376	          ...(body['models'] !== undefined ? { models: body['models'] } : {}),
377	        });
378	      else if (body['state'] === 'not-ready') fake.preflightResult = notReadyClaudePreflight;
379	      else throw new E2eControlError("preflight state must be 'ready' or 'not-ready'");
380	      return { ok: true };
381	    }
382	    case '/harness/termination': {
383	      const instance = selectedInstance(body);
384	      const { harness, fake } = selectedHarness(instance, body);
385	      if (harness !== 'claude' || !(fake instanceof E2eClaudeHarness))
386	        throw new E2eControlError(
387	          'termination controls are available only for the Claude E2E fake',
388	        );
389	      if (body['mode'] !== 'confirmed' && body['mode'] !== 'unconfirmed')
390	        throw new E2eControlError("termination mode must be 'confirmed' or 'unconfirmed'");
391	      fake.termination = body['mode'];
392	      return { ok: true };
393	    }
394	    case '/deciders':
395	      target.jev.isAvailable = body['jev'] !== false;
396	      target.codex.isAvailable = body['codex'] !== false;
397	      return { ok: true };
398	    case '/deciders/requests':
399	      return { routes: selectedInstance(body).app.codex.routes };
400	    case '/deciders/route':
401	      target.jev.choose = (request) => {
402	        target.jev.choices.push(request);
403	        const optionId =
404	          typeof body['optionId'] === 'string' ? body['optionId'] : request.options[0]!.id;
405	        return Promise.resolve({
406	          type: 'choice' as const,
407	          optionId,
408	          confidence: 1,
409	          probabilities: Object.fromEntries(
410	            request.options.map((option) => [option.id, option.id === optionId ? 1 : 0]),
411	          ),
412	        });
413	      };
414	      return { ok: true };
415	    case '/structured': {
416	      const queue = [...((body['responses'] as unknown[] | undefined) ?? [])];
417	      selectedInstance(body).app.structured.respondWith(() =>
418	        queue.length > 1 ? queue.shift() : queue[0],
419	      );
420	      return { ok: true };
421	    }
422	    case '/catalog/upsert':
423	      await selectedInstance(body).app.container.repos.catalog.upsert(
424	        ModelCatalogEntrySchema.parse(
425	          Object.fromEntries(Object.entries(body).filter(([key]) => key !== 'instanceId')),
426	        ),
427	      );
428	      return { ok: true };
429	    case '/timers/poll':
430	      await target.container.timers.poll();
431	      return { ok: true };
432	    case '/apps/live': {
433	      // The real adapters (Codex CLI), for the LIVE=1 spec only. Costs subscription quota.
434	      const dataDir = await mkdtemp(join(tmpdir(), 'gg-e2e-live-'));
435	      const container = await createContainer(
436	        loadConfig({
437	          GG_DATA_DIR: dataDir,
438	          GG_DB_URL: ':memory:',
439	          GG_SWAGGER_UI: 'false',
440	          GG_MASTER_KEY: Buffer.alloc(32, 7).toString('base64'),
441	          GG_DEFAULTS: JSON.stringify({
442	            byHarness: { codex: { model: 'gpt-6-luna', effort: 'low' } },
443	          }),
444	          GG_WEB_DIST: dist,
445	        }),
446	        { startTimers: false },
447	      );
448	      await container.start();
449	      const live = await buildApp(container, { logger: false });
450	      closers.push(async () => {
451	        await live.close();
452	        await container.stop();
453	        await rm(dataDir, { recursive: true, force: true }).catch(() => undefined);
454	      });
455	      return { url: await live.listen({ host: '127.0.0.1', port: 0 }) };
456	    }
457	    case '/classifier/start': {
458	      // Defaults answer the first Choice route, true Noul, or Score index zero.
459	      const fake = await startFakeClassifierEndpoint();
460	      classifiers.set(fake.endpoint, fake);
461	      closers.push(async () => {
462	        if (classifiers.delete(fake.endpoint)) await fake.close();
463	        classifierReplies.delete(fake.endpoint);
464	      });
465	      return { endpoint: fake.endpoint };
466	    }
467	    case '/classifier/requests': {
468	      const fake = classifiers.get(String(body['endpoint']));
469	      if (!fake) throw new Error(`no fake classifier at ${String(body['endpoint'])}`);
470	      return {
471	        requests: fake.requests.map((r) => ({
472	          method: r.method,
473	          url: r.url,
474	          model: r.body.model,
475	          type: r.body.questions.answer.type,
476	          bearer: r.authorization !== undefined,
477	          labels: Object.keys(r.body.questions.answer.criteria),
478	        })),
479	        remainingReplies: classifierReplies.get(fake.endpoint)?.length ?? null,
480	      };
481	    }
482	    case '/classifier/stop': {
483	      const endpoint = String(body['endpoint']);
484	      const fake = classifiers.get(endpoint);
485	      if (!fake) throw new E2eControlError('No fake classifier at ' + endpoint);
486	      classifiers.delete(endpoint);
487	      classifierReplies.delete(endpoint);
488	      await fake.close();
489	      return { closed: true };
490	    }
491	    case '/classifier/replies': {
492	      const endpoint = String(body['endpoint']);
493	      const fake = classifiers.get(endpoint);
494	      if (!fake) throw new E2eControlError('No fake classifier at ' + endpoint);
495	      const parsed = ClassifierReplySchema.array().min(1).max(16).safeParse(body['replies']);
496	      if (!parsed.success) throw new E2eControlError('Expected 1–16 valid Noul or Score replies.');
497	      classifierReplies.set(endpoint, parsed.data);
498	      fake.respondWith((call) => {
499	        const question = call.body.questions.answer;
500	        const next = classifierReplies.get(endpoint)?.shift();
501	        if (!next || next.type !== question.type)
502	          return {
503	            status: 400,
504	            body: { error: 'Unexpected primitive request or reply queue exhausted.' },
505	          };
506	        if (next.type === 'noul')
507	          return {
508	            body: {
509	              model: call.body.model,
510	              answers: { answer: { type: 'noul', noul: next.trueProbability } },
511	            },
512	          };
513	        if (question.type !== 'score' || next.score > question.criteria.length - 1)
514	          return { status: 400, body: { error: 'Score reply is outside the declared rubric.' } };
515	        return {
516	          body: {
517	            model: call.body.model,
518	            answers: {
519	              answer: {
520	                type: 'score',
521	                score: next.score,
522	                confidence: next.confidence,
523	                legend: Object.fromEntries(
524	                  question.criteria.map((anchor, index) => [String(index), anchor]),
525	                ),
526	                probabilities: next.probabilities,
527	              },
528	            },
529	          },
530	        };
531	      });
532	      return { configured: true, queued: parsed.data.length };
533	    }
534	    case '/classifier/respond-noul': {
535	      const fake = classifiers.get(String(body['endpoint']));
536	      const trueProbability = body['trueProbability'];
537	      if (!fake) throw new Error(`no fake classifier at ${String(body['endpoint'])}`);
538	      if (typeof trueProbability !== 'number' || trueProbability < 0 || trueProbability > 1)
539	        throw new E2eControlError('trueProbability must be between 0 and 1');
540	      fake.respondWith((request) => {
541	        if (request.body.questions.answer.type !== 'noul')
542	          return { status: 400, body: { error: 'This E2E response is for Noul only.' } };
543	        return {
544	          body: {
545	            model: request.body.model,
546	            answers: { answer: { type: 'noul', noul: trueProbability } },
547	          },
548	        };
549	      });
550	      return { configured: true };
551	    }
552	    case '/thread-history': {
553	      const id = z.string().parse(body['instanceId']);
554	      const history = threadHistories.get(id);
555	      if (!history) throw new E2eControlError('unknown thread-history instance');
556	      switch (body['action']) {
557	        case 'start':
558	          await history.manager.start();
559	          await history.manager.waitForIdle();
560	          break;
561	        case 'working':
562	          await history.working;
563	          break;
564	        case 'release':
565	          history.release();
566	          await history.manager.waitForIdle();
567	          break;
568	        case 'flush':
569	          await history.snapshots.flush();
570	          break;
571	        case 'snapshot': {
572	          const runId = z.string().parse(body['runId']);
573	          return {
574	            snapshot: await history.repos.runs.getThread(runId),
575	            bytes: await history.bytes(runId),
576	          };
577	        }
578	        default:
579	          throw new E2eControlError('unknown thread-history action');
580	      }
581	      return { ok: true };
582	    }
583	    case '/apps/stored-loop-defaults': {
584	      const status = z.enum(['draft', 'published']).parse(body['status']);
585	      const dataDir = await mkdtemp(join(tmpdir(), 'gg-wp-f3-270-editor-'));
586	      let fixture: TestApp | undefined;
587	      try {
588	        // Preserve the genuine pre-0019 store. Only the normal gateway startup migrates it.
589	        const stored = await storeLoopBefore({
590	          dataDir,
591	          tag: '0019_completion_deadline_defaults',
592	          definition: body['definition'],
593	          publish: status === 'published',
594	          remove: ['$.settings.structuredTimeoutMs', '$.settings.runDeadlineSeconds'],
595	        });
596	        fixture = await createTestApp({
597	          env: { GG_DATA_DIR: dataDir, GG_DB_URL: stored.url, GG_WEB_DIST: dist },
598	        });
599	        const pendingMigrations = await fixture.container.handle.pendingMigrations();
600	        const url = await fixture.app.listen({ host: '127.0.0.1', port: 0 });
601	        apps.push(fixture);
602	        // App teardown closes its store before the externally supplied directory is removed.
603	        closers.push(() => rm(dataDir, { recursive: true, force: true, maxRetries: 5 }));
604	        return { url, loopId: stored.loopId, pendingMigrations };
605	      } catch (error) {
606	        await fixture?.close();
607	        await rm(dataDir, { recursive: true, force: true, maxRetries: 5 });
608	        throw error;
609	      }
610	    }
611	    case '/apps': {
612	      if (body['threadHistory'] === true) {
613	        const history = await createThreadHistoryFixture(dist);
614	        history.manager.stop();
615	        const instanceId = 'thread-history-' + nextInstanceId++;
616	        const url = await history.app.listen({ host: '127.0.0.1', port: 0 });
617	        threadHistories.set(instanceId, history);
618	        closers.push(() => history.close());
619	        return { instanceId, url, loopId: history.loopId };
620	      }
621	      const extra = await startApp(
622	        (body['env'] as Record<string, string> | undefined) ?? {},
623	        body['requireApiKey'] === true,
624	        // The real catalog, secret resolution, and HTTP transport for classifiers (#43).
625	        body['realClassifiers'] === true,
626	        {
627	          claude: body['claude'] === true,
628	          ...(body['tempPrefix'] === 'gg-wp-e3-' ? { tempPrefix: 'gg-wp-e3-' } : {}),
629	        },
630	      );
631	      // A key minted directly in the store: with GG_REQUIRE_API_KEY even POST /api-keys needs one.
632	      const { token } = await extra.app.container.repos.apiKeys.create('local', 'e2e', ['*']);
633	      return { instanceId: extra.id, url: extra.url, token };
634	    }
635	    default:
636	      response.statusCode = 404;
637	      return { error: `unknown control path ${request.url ?? ''}` };
638	  }
639	}
640	
641	const controlServer = createServer((request, response) => {
642	  control(request, response).then(
643	    (result) => {
644	      response.setHeader('content-type', 'application/json');
645	      response.end(JSON.stringify(result));
646	    },
647	    (error: unknown) => {
648	      response.statusCode = error instanceof E2eControlError ? error.statusCode : 500;
649	      response.end(JSON.stringify({ error: String(error) }));
650	    },
651	  );
652	});
653	await new Promise<void>((done) =>
654	  controlServer.listen(Number(process.env['GG_E2E_CONTROL_PORT'] ?? 0), '127.0.0.1', done),
655	);
656	const controlAddress = controlServer.address();
657	const controlPort = typeof controlAddress === 'object' && controlAddress ? controlAddress.port : 0;
658	
659	console.log(`GG_E2E_CONTROL http://127.0.0.1:${controlPort}`);
660	console.log(`GG_E2E_READY ${main.url}`);
661	
662	let stopping = false;
663	async function stop(): Promise<void> {
664	  if (stopping) return;
665	  stopping = true;
666	  controlServer.close();
667	  for (const instance of instances.values()) await setApiListening(instance, true);
668	  await writeFile(workerPath, originalWorker);
669	  for (const app of apps) await app.close();
670	  for (const close of closers) await close();
671	  process.exit(0);
672	}
673	if (process.env['GG_E2E_KEEP_STDIN'] !== '1') {
674	  process.stdin.on('data', () => void stop());
675	  process.stdin.on('end', () => void stop());
676	}
677	process.on('SIGINT', () => void stop());
678	process.on('SIGTERM', () => void stop());
