/**
 * E2E backend: the real API in this process over an in-memory database with the fake harness
 * (`createTestApp`), serving the built web app from apps/web/dist through the static plugin
 * (GG_WEB_DIST). Listens on an ephemeral port and prints `GG_E2E_READY <url>`; writing anything to
 * stdin, or closing it, shuts it down cleanly.
 *
 * A second, loopback-only control server (`GG_E2E_CONTROL <url>`) lets specs script the fakes:
 * harness turns, decider availability, structured completions, timer polls, and extra API
 * instances with other configuration (for example `GG_REQUIRE_API_KEY=true`).
 */
import { existsSync } from 'node:fs';
import { z } from 'zod';
import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { buildApp, createContainer, loadConfig } from '@graphgoblin/api';
import { readinessMessage } from '@graphgoblin/domain';
import {
  createTestApp,
  createThreadHistoryFixture,
  startFakeClassifierEndpoint,
  storeLoopBefore,
  voiceProbeSample,
  type TestApp,
} from '@graphgoblin/api/testing';
import type { HarnessEvent, HarnessStartRequest, HarnessSession } from '@graphgoblin/engine';
import { FakeHarness, type ScriptedTurn } from '@graphgoblin/engine/testing';
import {
  HarnessPreflightSchema,
  ModelCatalogEntrySchema,
  type HarnessPreflight,
} from '@graphgoblin/contracts';
import { originalWorker as cleanWorker } from '../src/e2e-support/worker.js';

// A disposable build copy allows regression seeding without changing the normal build.
const dist = resolve(
  process.env['GG_E2E_WEB_DIST'] ?? resolve(dirname(fileURLToPath(import.meta.url)), '..', 'dist'),
);
if (!existsSync(join(dist, 'index.html'))) {
  console.error(
    `No web build at ${dist}. Run \`pnpm build\` (or \`pnpm --filter @graphgoblin/web build\`) first.`,
  );
  process.exit(1);
}

interface E2eInstance {
  id: string;
  app: TestApp;
  url: string;
  harnesses: Partial<Record<'codex' | 'claude', FakeHarness>>;
}

class E2eControlError extends Error {
  readonly statusCode = 400;
}

const apps: TestApp[] = [];
const instances = new Map<string, E2eInstance>();
const storageCapacities = new Map<string, { availableBytes: number }>();
const threadHistories = new Map<string, Awaited<ReturnType<typeof createThreadHistoryFixture>>>();
const closers: (() => Promise<void>)[] = [];
let nextInstanceId = 1;
/** Loopback primitive endpoints started for classifier specs, by their API root. */
const classifiers = new Map<string, Awaited<ReturnType<typeof startFakeClassifierEndpoint>>>();
const ClassifierReplySchema = z.discriminatedUnion('type', [
  z.strictObject({
    type: z.literal('noul'),
    trueProbability: z.number().min(0).max(1),
  }),
  z.strictObject({
    type: z.literal('score'),
    score: z.number().min(0),
    confidence: z.number().min(0).max(1),
    probabilities: z.record(z.string(), z.number().min(0).max(1)),
  }),
]);
const classifierReplies = new Map<string, z.infer<typeof ClassifierReplySchema>[]>();
const claudeEfforts = ['low', 'medium', 'high', 'xhigh', 'max'] as const;
const readyClaudePreflight = HarnessPreflightSchema.parse({
  state: 'ready',
  ok: true,
  version: '2.1.285 (E2E fake)',
  authenticated: true,
  problems: [],
  authMethod: 'claude.ai',
  supportedPolicies: [
    {
      sandbox: 'read-only',
      approval: 'never',
      permissionMode: 'dontAsk',
      tools: ['Read', 'Glob', 'Grep'],
      authMethod: 'claude.ai',
      boundary: 'builtin-tools',
      network: 'unconfined',
    },
    {
      sandbox: 'danger-full-access',
      approval: 'never',
      permissionMode: 'dontAsk',
      tools: ['Read', 'Glob', 'Grep', 'Edit', 'Write', 'Bash'],
      authMethod: 'claude.ai',
      boundary: 'unconfined',
      network: 'unconfined',
    },
  ],
  models: [
    {
      model: 'claude-opus-5-5',
      efforts: claudeEfforts,
    },
    {
      model: 'claude-fable-5-1',
      efforts: claudeEfforts,
    },
    {
      model: 'claude-sonnet-5-5',
      efforts: claudeEfforts,
    },
    {
      model: 'claude-haiku-5-5',
      efforts: claudeEfforts,
    },
  ],
});
const notReadyClaudePreflight: HarnessPreflight = {
  ...readyClaudePreflight,
  state: 'auth',
  ok: false,
  authenticated: false,
  problems: [readinessMessage('claude', 'auth', 'Claude is not signed in.')],
  supportedPolicies: [],
};

class E2eClaudeHarness extends FakeHarness {
  termination: 'confirmed' | 'unconfirmed' = 'confirmed';
  private terminationSession = 0;

  constructor() {
    super([], 'claude');
    this.preflightResult = readyClaudePreflight;
  }

  override start(request: HarnessStartRequest, signal: AbortSignal): HarnessSession {
    if (this.termination === 'confirmed') return super.start(request, signal);
    this.started.push(request);
    this.terminationSession += 1;
    const sessionId = 'fake-claude-unconfirmed-' + this.terminationSession;
    const error = Object.assign(
      new Error('Termination not confirmed; stop the E2E fake before retrying.'),
      { code: 'HARNESS_TERMINATION_UNCONFIRMED', retriable: false },
    );
    const result: HarnessSession['result'] = new Promise((_, reject) => {
      if (signal.aborted) reject(error);
      else signal.addEventListener('abort', () => reject(error), { once: true });
    });
    result.catch(() => undefined);
    const events = async function* (): AsyncGenerator<HarnessEvent> {
      yield { type: 'session', sessionId, mode: 'fresh' };
      await result.catch(() => undefined);
      yield {
        type: 'error',
        code: error.code,
        message: error.message,
        retriable: false,
        submission: 'delivery-uncertain',
      };
    };
    return {
      sessionId: Promise.resolve(sessionId),
      events: events(),
      result,
      cancel: () => Promise.reject(error),
    };
  }
}

async function startApp(
  env: Record<string, string> = {},
  requireApiKey = false,
  realClassifiers = false,
  options: { claude?: boolean; id?: string; tempPrefix?: string } = {},
) {
  const id = options.id ?? 'e2e-instance-' + nextInstanceId++;
  const codex = new FakeHarness([], 'codex');
  const claude = options.claude ? new E2eClaudeHarness() : undefined;
  const harnesses = { codex, ...(claude ? { claude } : {}) };
  const storage = { availableBytes: 50 * 1024 ** 3 };
  const app = await createTestApp({
    storageCapacity: {
      read: () =>
        Promise.resolve({ totalBytes: 100 * 1024 ** 3, availableBytes: storage.availableBytes }),
    },
    ...(options.tempPrefix ? { tempPrefix: options.tempPrefix } : {}),
    env: { GG_WEB_DIST: dist, ...env },
    requireApiKey,
    realClassifiers,
    harnesses,
  });
  apps.push(app);
  const url = await app.app.listen({
    host: '127.0.0.1',
    port: id === 'main' ? Number(process.env['GG_E2E_MAIN_PORT'] ?? 0) : 0,
  });
  const instance: E2eInstance = { id, app, url, harnesses };
  storageCapacities.set(id, storage);
  instances.set(id, instance);
  return instance;
}

const main = await startApp({}, false, false, { id: 'main' });
const workerPath = join(dist, 'sw.js');
// A stopped legacy-fallback test can leave its marked omission in the disposable build. Recover
// the exact original import expression before taking the baseline, just as build markers recover.
const originalWorker = cleanWorker(await readFile(workerPath, 'utf8')).replace(
  /\/\* E2E legacy guard: (importScripts\(\s*(["'])chat-update-worker\.js\2\s*\)) \*\/void 0/g,
  '$1',
);
const guardImport = /\bimportScripts\(\s*(["'])chat-update-worker\.js\1\s*\)/;
if (!guardImport.test(originalWorker) || !existsSync(join(dist, 'chat-update-worker.js')))
  throw new Error(
    'E2E PWA checks require the current built worker and chat-update-worker.js. Rebuild the web app.',
  );
// Keep the real precache/navigation worker. Omitting its helper models an active pre-guard build
// with no capability response; the reversible marker also preserves interrupted-run recovery.
const legacyWorker = originalWorker.replace(
  guardImport,
  (statement) => `/* E2E legacy guard: ${statement} */void 0`,
);
let workerBuild = 0;

/** Drop real HTTP connections, then reuse the same listener and in-memory API state. */
async function setApiListening(instance: E2eInstance, listening: boolean): Promise<void> {
  const server = instance.app.app.server;
  if (listening === server.listening) return;
  if (listening) {
    await new Promise<void>((done, reject) => {
      server.once('error', reject);
      server.listen(Number(new URL(instance.url).port), '127.0.0.1', () => {
        server.removeListener('error', reject);
        done();
      });
    });
  } else {
    await new Promise<void>((done, reject) => {
      server.close((error) => (error ? reject(error) : done()));
      server.closeAllConnections();
    });
  }
}

/** A scripted turn as JSON: `items` may be a count of generated progress items. */
interface TurnSpec {
  matchPrompt?: string;
  items?: number | ScriptedTurn['items'];
  finalText?: string;
  structured?: unknown;
  error?: ScriptedTurn['error'];
  delayMs?: number;
}

function toTurn(spec: TurnSpec): ScriptedTurn {
  const { matchPrompt, items, error, ...rest } = spec;
  return {
    ...rest,
    ...(error ? { error } : {}),
    ...(matchPrompt ? { match: (request) => request.prompt.includes(matchPrompt) } : {}),
    ...(typeof items === 'number'
      ? {
          items: Array.from({ length: items }, (_, i) => ({
            id: `item-${i + 1}`,
            type: 'message' as const,
            summary: `streamed item ${i + 1}`,
          })),
        }
      : items
        ? { items }
        : {}),
  };
}

async function readJson(request: IncomingMessage): Promise<Record<string, unknown>> {
  let body = '';
  for await (const chunk of request) body += String(chunk);
  return body ? (JSON.parse(body) as Record<string, unknown>) : {};
}

function selectedInstance(body: Record<string, unknown>): E2eInstance {
  const id = typeof body['instanceId'] === 'string' ? body['instanceId'] : 'main';
  const instance = instances.get(id);
  if (!instance) throw new E2eControlError("unknown E2E instance '" + id + "'");
  return instance;
}

function selectedHarness(
  instance: E2eInstance,
  body: Record<string, unknown>,
): { harness: 'codex' | 'claude'; fake: FakeHarness } {
  const requested = body['harness'] === undefined ? 'codex' : body['harness'];
  if (requested !== 'codex' && requested !== 'claude') {
    const label = typeof requested === 'string' ? requested : typeof requested;
    throw new E2eControlError("unknown E2E harness '" + label + "'");
  }
  const fake = instance.harnesses[requested];
  if (!fake)
    throw new E2eControlError(
      "harness '" + requested + "' is not enabled for E2E instance '" + instance.id + "'",
    );
  return { harness: requested, fake };
}

async function control(request: IncomingMessage, response: ServerResponse): Promise<unknown> {
  const body = await readJson(request);
  const target = main.app;
  switch (request.url) {
    case '/voice/public-sample':
      // Public fixture bytes for Chromium's fake device, never ambient microphone input.
      return { wavBase64: voiceProbeSample().toString('base64') };
    case '/storage/capacity': {
      const instance = selectedInstance(body);
      storageCapacities.get(instance.id)!.availableBytes = z
        .number()
        .int()
        .nonnegative()
        .parse(body['availableBytes']);
      instance.app.clock.advance(60_000);
      await instance.app.container.historyCleanup.poll();
      return instance.app.container.historyCleanup.status();
    }
    case '/clock/advance':
      selectedInstance(body).app.clock.advance(
        z.number().int().positive().parse(body['milliseconds']),
      );
      return { ok: true };
    case '/api/listener':
      await setApiListening(selectedInstance(body), body['listening'] !== false);
      return { ok: true };
    case '/worker/build': {
      const mode = z.enum(['guarded', 'legacy']).parse(body['mode'] ?? 'guarded');
      workerBuild += 1;
      await writeFile(
        workerPath,
        `${mode === 'legacy' ? legacyWorker : originalWorker}\n// E2E build ${workerBuild}\n`,
      );
      return { build: workerBuild, mode };
    }
    case '/worker/reset':
      await writeFile(workerPath, originalWorker);
      return { ok: true };
    case '/harness/script':
      selectedHarness(selectedInstance(body), body).fake.script(
        ((body['turns'] as TurnSpec[] | undefined) ?? []).map(toTurn),
      );
      return { ok: true };
    case '/harness/requests': {
      const instance = selectedInstance(body);
      const { harness, fake } = selectedHarness(instance, body);
      const detailed = body['instanceId'] !== undefined || body['harness'] !== undefined;
      return {
        started: fake.started.map((r) => ({
          model: r.model,
          effort: r.effort,
          ...(detailed ? { harness, options: r.options } : {}),
        })),
      };
    }
    case '/harness/preflight': {
      const instance = selectedInstance(body);
      const { harness, fake } = selectedHarness(instance, body);
      if (harness !== 'claude' || !(fake instanceof E2eClaudeHarness))
        throw new E2eControlError('preflight controls are available only for the Claude E2E fake');
      if (body['state'] === 'ready')
        fake.preflightResult = HarnessPreflightSchema.parse({
          ...readyClaudePreflight,
          ...(body['models'] !== undefined ? { models: body['models'] } : {}),
        });
      else if (body['state'] === 'not-ready') fake.preflightResult = notReadyClaudePreflight;
      else throw new E2eControlError("preflight state must be 'ready' or 'not-ready'");
      return { ok: true };
    }
    case '/harness/termination': {
      const instance = selectedInstance(body);
      const { harness, fake } = selectedHarness(instance, body);
      if (harness !== 'claude' || !(fake instanceof E2eClaudeHarness))
        throw new E2eControlError(
          'termination controls are available only for the Claude E2E fake',
        );
      if (body['mode'] !== 'confirmed' && body['mode'] !== 'unconfirmed')
        throw new E2eControlError("termination mode must be 'confirmed' or 'unconfirmed'");
      fake.termination = body['mode'];
      return { ok: true };
    }
    case '/deciders':
      target.jev.isAvailable = body['jev'] !== false;
      target.codex.isAvailable = body['codex'] !== false;
      return { ok: true };
    case '/deciders/requests':
      return { routes: selectedInstance(body).app.codex.routes };
    case '/deciders/route':
      target.jev.choose = (request) => {
        target.jev.choices.push(request);
        const optionId =
          typeof body['optionId'] === 'string' ? body['optionId'] : request.options[0]!.id;
        return Promise.resolve({
          type: 'choice' as const,
          optionId,
          confidence: 1,
          probabilities: Object.fromEntries(
            request.options.map((option) => [option.id, option.id === optionId ? 1 : 0]),
          ),
        });
      };
      return { ok: true };
    case '/structured': {
      const queue = [...((body['responses'] as unknown[] | undefined) ?? [])];
      selectedInstance(body).app.structured.respondWith(() =>
        queue.length > 1 ? queue.shift() : queue[0],
      );
      return { ok: true };
    }
    case '/catalog/upsert':
      await selectedInstance(body).app.container.repos.catalog.upsert(
        ModelCatalogEntrySchema.parse(
          Object.fromEntries(Object.entries(body).filter(([key]) => key !== 'instanceId')),
        ),
      );
      return { ok: true };
    case '/timers/poll':
      await target.container.timers.poll();
      return { ok: true };
    case '/apps/live': {
      // The real adapters (Codex CLI), for the LIVE=1 spec only. Costs subscription quota.
      const dataDir = await mkdtemp(join(tmpdir(), 'gg-e2e-live-'));
      const container = await createContainer(
        loadConfig({
          GG_DATA_DIR: dataDir,
          GG_DB_URL: ':memory:',
          GG_SWAGGER_UI: 'false',
          GG_MASTER_KEY: Buffer.alloc(32, 7).toString('base64'),
          GG_DEFAULTS: JSON.stringify({
            byHarness: { codex: { model: 'gpt-6-luna', effort: 'low' } },
          }),
          GG_WEB_DIST: dist,
        }),
        { startTimers: false },
      );
      await container.start();
      const live = await buildApp(container, { logger: false });
      closers.push(async () => {
        await live.close();
        await container.stop();
        await rm(dataDir, { recursive: true, force: true }).catch(() => undefined);
      });
      return { url: await live.listen({ host: '127.0.0.1', port: 0 }) };
    }
    case '/classifier/start': {
      // Defaults answer the first Choice route, true Noul, or Score index zero.
      const fake = await startFakeClassifierEndpoint();
      classifiers.set(fake.endpoint, fake);
      closers.push(async () => {
        if (classifiers.delete(fake.endpoint)) await fake.close();
        classifierReplies.delete(fake.endpoint);
      });
      return { endpoint: fake.endpoint };
    }
    case '/classifier/requests': {
      const fake = classifiers.get(String(body['endpoint']));
      if (!fake) throw new Error(`no fake classifier at ${String(body['endpoint'])}`);
      return {
        requests: fake.requests.map((r) => ({
          method: r.method,
          url: r.url,
          model: r.body.model,
          type: r.body.questions.answer.type,
          bearer: r.authorization !== undefined,
          labels: Object.keys(r.body.questions.answer.criteria),
        })),
        remainingReplies: classifierReplies.get(fake.endpoint)?.length ?? null,
      };
    }
    case '/classifier/stop': {
      const endpoint = String(body['endpoint']);
      const fake = classifiers.get(endpoint);
      if (!fake) throw new E2eControlError('No fake classifier at ' + endpoint);
      classifiers.delete(endpoint);
      classifierReplies.delete(endpoint);
      await fake.close();
      return { closed: true };
    }
    case '/classifier/replies': {
      const endpoint = String(body['endpoint']);
      const fake = classifiers.get(endpoint);
      if (!fake) throw new E2eControlError('No fake classifier at ' + endpoint);
      const parsed = ClassifierReplySchema.array().min(1).max(16).safeParse(body['replies']);
      if (!parsed.success) throw new E2eControlError('Expected 1–16 valid Noul or Score replies.');
      classifierReplies.set(endpoint, parsed.data);
      fake.respondWith((call) => {
        const question = call.body.questions.answer;
        const next = classifierReplies.get(endpoint)?.shift();
        if (!next || next.type !== question.type)
          return {
            status: 400,
            body: { error: 'Unexpected primitive request or reply queue exhausted.' },
          };
        if (next.type === 'noul')
          return {
            body: {
              model: call.body.model,
              answers: { answer: { type: 'noul', noul: next.trueProbability } },
            },
          };
        if (question.type !== 'score' || next.score > question.criteria.length - 1)
          return { status: 400, body: { error: 'Score reply is outside the declared rubric.' } };
        return {
          body: {
            model: call.body.model,
            answers: {
              answer: {
                type: 'score',
                score: next.score,
                confidence: next.confidence,
                legend: Object.fromEntries(
                  question.criteria.map((anchor, index) => [String(index), anchor]),
                ),
                probabilities: next.probabilities,
              },
            },
          },
        };
      });
      return { configured: true, queued: parsed.data.length };
    }
    case '/classifier/respond-noul': {
      const fake = classifiers.get(String(body['endpoint']));
      const trueProbability = body['trueProbability'];
      if (!fake) throw new Error(`no fake classifier at ${String(body['endpoint'])}`);
      if (typeof trueProbability !== 'number' || trueProbability < 0 || trueProbability > 1)
        throw new E2eControlError('trueProbability must be between 0 and 1');
      fake.respondWith((request) => {
        if (request.body.questions.answer.type !== 'noul')
          return { status: 400, body: { error: 'This E2E response is for Noul only.' } };
        return {
          body: {
            model: request.body.model,
            answers: { answer: { type: 'noul', noul: trueProbability } },
          },
        };
      });
      return { configured: true };
    }
    case '/thread-history': {
      const id = z.string().parse(body['instanceId']);
      const history = threadHistories.get(id);
      if (!history) throw new E2eControlError('unknown thread-history instance');
      switch (body['action']) {
        case 'start':
          await history.manager.start();
          await history.manager.waitForIdle();
          break;
        case 'working':
          await history.working;
          break;
        case 'release':
          history.release();
          await history.manager.waitForIdle();
          break;
        case 'flush':
          await history.snapshots.flush();
          break;
        case 'snapshot': {
          const runId = z.string().parse(body['runId']);
          return {
            snapshot: await history.repos.runs.getThread(runId),
            bytes: await history.bytes(runId),
          };
        }
        default:
          throw new E2eControlError('unknown thread-history action');
      }
      return { ok: true };
    }
    case '/apps/stored-loop-defaults': {
      const status = z.enum(['draft', 'published']).parse(body['status']);
      const dataDir = await mkdtemp(join(tmpdir(), 'gg-wp-f3-270-editor-'));
      let fixture: TestApp | undefined;
      try {
        // Preserve the genuine pre-0019 store. Only the normal gateway startup migrates it.
        const stored = await storeLoopBefore({
          dataDir,
          tag: '0019_completion_deadline_defaults',
          definition: body['definition'],
          publish: status === 'published',
          remove: ['$.settings.structuredTimeoutMs', '$.settings.runDeadlineSeconds'],
        });
        fixture = await createTestApp({
          env: { GG_DATA_DIR: dataDir, GG_DB_URL: stored.url, GG_WEB_DIST: dist },
        });
        const pendingMigrations = await fixture.container.handle.pendingMigrations();
        const url = await fixture.app.listen({ host: '127.0.0.1', port: 0 });
        apps.push(fixture);
        // App teardown closes its store before the externally supplied directory is removed.
        closers.push(() => rm(dataDir, { recursive: true, force: true, maxRetries: 5 }));
        return { url, loopId: stored.loopId, pendingMigrations };
      } catch (error) {
        await fixture?.close();
        await rm(dataDir, { recursive: true, force: true, maxRetries: 5 });
        throw error;
      }
    }
    case '/apps': {
      if (body['threadHistory'] === true) {
        const history = await createThreadHistoryFixture(dist);
        history.manager.stop();
        const instanceId = 'thread-history-' + nextInstanceId++;
        const url = await history.app.listen({ host: '127.0.0.1', port: 0 });
        threadHistories.set(instanceId, history);
        closers.push(() => history.close());
        return { instanceId, url, loopId: history.loopId };
      }
      const extra = await startApp(
        (body['env'] as Record<string, string> | undefined) ?? {},
        body['requireApiKey'] === true,
        // The real catalog, secret resolution, and HTTP transport for classifiers (#43).
        body['realClassifiers'] === true,
        {
          claude: body['claude'] === true,
          ...(body['tempPrefix'] === 'gg-wp-e3-' ? { tempPrefix: 'gg-wp-e3-' } : {}),
        },
      );
      // A key minted directly in the store: with GG_REQUIRE_API_KEY even POST /api-keys needs one.
      const { token } = await extra.app.container.repos.apiKeys.create('local', 'e2e', ['*']);
      return { instanceId: extra.id, url: extra.url, token };
    }
    default:
      response.statusCode = 404;
      return { error: `unknown control path ${request.url ?? ''}` };
  }
}

const controlServer = createServer((request, response) => {
  control(request, response).then(
    (result) => {
      response.setHeader('content-type', 'application/json');
      response.end(JSON.stringify(result));
    },
    (error: unknown) => {
      response.statusCode = error instanceof E2eControlError ? error.statusCode : 500;
      response.end(JSON.stringify({ error: String(error) }));
    },
  );
});
await new Promise<void>((done) =>
  controlServer.listen(Number(process.env['GG_E2E_CONTROL_PORT'] ?? 0), '127.0.0.1', done),
);
const controlAddress = controlServer.address();
const controlPort = typeof controlAddress === 'object' && controlAddress ? controlAddress.port : 0;

console.log(`GG_E2E_CONTROL http://127.0.0.1:${controlPort}`);
console.log(`GG_E2E_READY ${main.url}`);

let stopping = false;
async function stop(): Promise<void> {
  if (stopping) return;
  stopping = true;
  controlServer.close();
  for (const instance of instances.values()) await setApiListening(instance, true);
  await writeFile(workerPath, originalWorker);
  for (const app of apps) await app.close();
  for (const close of closers) await close();
  process.exit(0);
}
if (process.env['GG_E2E_KEEP_STDIN'] !== '1') {
  process.stdin.on('data', () => void stop());
  process.stdin.on('end', () => void stop());
}
process.on('SIGINT', () => void stop());
process.on('SIGTERM', () => void stop());

