import type { HTMLAttributes } from 'react';
import { variants } from '../../lib/variants.js';
import { ellipsize } from './ellipsis.js';

export type Tone = 'neutral' | 'good' | 'bad' | 'warn' | 'info';

/**
 * Status tones: blue means success and orange failure (colour-blind safe), amber waiting or
 * attention, violet running or information. Anything that carries meaning pairs a tone with an
 * icon or a word, never colour alone.
 */
const TONE_CLASSES: Record<Tone, string> = {
  neutral: 'bg-status-neutral-bg text-status-neutral-fg',
  good: 'bg-status-good-bg text-status-good-fg',
  bad: 'bg-status-bad-bg text-status-bad-fg',
  warn: 'bg-status-warn-bg text-status-warn-fg',
  info: 'bg-status-info-bg text-status-info-fg',
};

const badgeClasses = variants({
  // The transparent border becomes visible in forced-colours mode, where backgrounds are dropped.
  // A badge never grows wider than its container, nor widens a grid column; overlong text ends in
  // an ellipsis (ellipsize). It does not shrink in a flex row, as before.
  base: 'inline-flex max-w-full min-w-0 shrink-0 items-center rounded-full border border-transparent font-semibold leading-none whitespace-nowrap',
  variants: {
    tone: TONE_CLASSES,
    size: {
      sm: 'h-5 gap-1 px-[7px] text-[11px] [&_svg]:size-[11px]',
      md: 'h-6 gap-[5px] px-2.5 text-xs has-[svg]:pl-[7px] [&_svg]:size-[13px] [&_svg]:stroke-[2.5]',
    },
  },
  defaults: { tone: 'neutral', size: 'md' },
});

export function Alert({
  tone = 'bad',
  title,
  className,
  children,
  onDismiss,
}: {
  tone?: Tone;
  title?: string;
  className?: string;
  children?: ReactNode;
  onDismiss?: () => void;
}) {
  const style = ALERT_TONES[tone];
  return (
    <div
      role={tone === 'bad' ? 'alert' : 'status'}
      className={cn(
        cn(
          'grid gap-x-3 gap-y-0.5 rounded-md border-l-4 px-4 py-3',
          onDismiss ? 'grid-cols-[auto_minmax(0,1fr)_auto]' : 'grid-cols-[auto_minmax(0,1fr)]',
        ),
        'min-w-0 text-sm leading-snug text-default wrap-anywhere',
        style.box,
        className,
      )}
    >
      <Icon name={style.icon} className={cn('row-span-2 mt-px size-[18px]', style.accent)} />
      {title ? <p className={cn('col-start-2 font-semibold', style.accent)}>{title}</p> : null}
      {children !== undefined && children !== null ? (
        <div className="col-start-2 min-w-0 [&_a]:text-link">{children}</div>

