  session.record.keyEnteredThroughPanel = true;
  return page;
}
function nonGetRequests(pages) {
  return pages.flatMap((p) => p.__net.filter((e) => e.kind === 'request' && e.method !== 'GET').map((e) => ({ tag: p.__tag, ...e })));
