}
const twoFrames = (page) =>
  page.evaluate(() => new Promise((done) => requestAnimationFrame(() => requestAnimationFrame(() => done()))));

async function newContext(browser, session, { theme, reducedMotion, viewport } = {}) {
  const context = await browser.newContext({
    baseURL: session.base,
    viewport: viewport ?? { width: 1440, height: 900 },
    serviceWorkers: 'block',
    reducedMotion: reducedMotion ?? 'no-preference',
    ...(session.storageState ? { storageState: session.storageState } : {}),
  });
  context.setDefaultTimeout(20_000);
  if (theme) await context.addInitScript((t) => localStorage.setItem('graphgoblin-theme', t), theme);
  return context;
}
async function enterKey(session, context) {
  const page = await context.newPage();
  instrument(page, `${session.label}-key`);
  await page.goto('/app/settings');
  await page.getByRole('heading', { name: 'API key required' }).waitFor({ timeout: 20_000 });
  await page.locator('#api-key-input').fill(session.token);
  await page.getByRole('button', { name: 'Use key' }).click();
  await waitCodex(page, session.firstState ?? 'ready', 30_000);
  await settle(page);
  session.storageState = await context.storageState(); // memory only (contains the QA key)
  session.record.keyEnteredThroughPanel = true;
  // Attempt 2: close the key tab so no second QueryClient shares later context-wide events
  // (run-01 C10 counted only one tab while this one also refetched on reconnect).
  await page.close();
  return page;
}

// Owned-process census by command line (Edge profile under the scratch root; fixture under E).
function census(tag) {
  const script =
    "$a = 'qa-scratch' + '\\i4-442-ui' + '-qa'; $b = 'fixture-' + 'codex.mjs'; " +
    'Get-CimInstance Win32_Process | Where-Object { $_.ProcessId -ne $PID -and $_.CommandLine -and ($_.CommandLine.Contains($a) -or $_.CommandLine.Contains($b)) } | ' +
    'ForEach-Object { [pscustomobject]@{ pid = $_.ProcessId; ppid = $_.ParentProcessId; name = $_.Name; cmd = $_.CommandLine.Substring(0, [Math]::Min(160, $_.CommandLine.Length)) } } | ConvertTo-Json -Compress';
  return new Promise((resolve) => {
    const child = spawn('powershell.exe', ['-NoProfile', '-NonInteractive', '-Command', script], { windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'] });
    let out = '';
    let err = '';
    child.stdout.on('data', (b) => (out += b));
    child.stderr.on('data', (b) => (err += b));
    const timer = setTimeout(() => child.kill(), 30_000);
    child.on('close', (code) => {
      clearTimeout(timer);
      let rows = [];
      try {
        rows = out.trim() ? [JSON.parse(out)].flat() : [];
      } catch {
        rows = [{ parseError: out.slice(0, 300) }];
      }
      rows = rows.filter((r) => r.pid !== process.pid && !/bash|cmd\.exe|powershell/i.test(r.name ?? ''));
      const entry = { tag, at: new Date().toISOString(), exitCode: code, stderr: err.slice(0, 300), rows };
      (results.census ??= []).push(entry);
      resolve(entry);
    });
  });
}
function serverPreflightCount(session) {
  const text = existsSync(session.outLog) ? readFileSync(session.outLog, 'utf8') : '';
  return text.split('\n').filter((l) => l.includes('"msg":"incoming request"') && l.includes('"url":"/harness/preflight"')).length;
}
function nonGetRequests(pages) {
  return pages.flatMap((p) => p.__net.filter((e) => e.kind === 'request' && e.method !== 'GET').map((e) => ({ tag: p.__tag, ...e })));
}
function saveNet(pages, name) {
  writeFileSync(join(RUN, `${name}-network.json`), redact(JSON.stringify(pages.map((p) => ({ tag: p.__tag, entries: p.__net })), null, 2)) + '\n');
}

