// Owned-process census by command line (Edge profile under the scratch root; fixture under E).
function census(tag) {
  const script =
    "$a = 'qa-scratch' + '\\i4-442-ui' + '-qa'; $b = 'fixture-' + 'codex.mjs'; " +
    'Get-CimInstance Win32_Process | Where-Object { $_.ProcessId -ne $PID -and $_.CommandLine -and ($_.CommandLine.Contains($a) -or $_.CommandLine.Contains($b)) } | ' +
    'ForEach-Object { [pscustomobject]@{ pid = $_.ProcessId; ppid = $_.ParentProcessId; name = $_.Name; cmd = $_.CommandLine.Substring(0, [Math]::Min(160, $_.CommandLine.Length)) } } | ConvertTo-Json -Compress';
  return new Promise((resolve) => {
    const child = spawn('powershell.exe', ['-NoProfile', '-NonInteractive', '-Command', script], { windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'] });
    let out = '';
    let err = '';
    child.stdout.on('data', (b) => (out += b));
    child.stderr.on('data', (b) => (err += b));
    const timer = setTimeout(() => child.kill(), 30_000);
    child.on('close', (code) => {
      clearTimeout(timer);
      let rows = [];
      try {
        rows = out.trim() ? [JSON.parse(out)].flat() : [];
      } catch {
        rows = [{ parseError: out.slice(0, 300) }];
      }
      rows = rows.filter((r) => r.pid !== process.pid && !/bash|cmd\.exe|powershell/i.test(r.name ?? ''));
      const entry = { tag, at: new Date().toISOString(), exitCode: code, stderr: err.slice(0, 300), rows };
      (results.census ??= []).push(entry);
      resolve(entry);
    });
  });
}
