  Object.assign(env, {
    HOME: home,
    USERPROFILE: home,
    APPDATA: home,
    LOCALAPPDATA: home,
    XDG_CONFIG_HOME: home,
    CODEX_HOME: home,
    TEMP: temp,
    TMP: temp,
    GG_DATA_DIR: join(S, 'stores', label),
    GG_REQUIRE_API_KEY: 'true',
    GG_LOG_LEVEL: 'info',
