        rows = [{ parseError: out.slice(0, 300) }];
      }
      rows = rows.filter((r) => r.pid !== process.pid && !/bash|cmd\.exe|powershell/i.test(r.name ?? ''));
      const entry = { tag, at: new Date().toISOString(), exitCode: code, stderr: err.slice(0, 300), rows };
      (results.census ??= []).push(entry);
      resolve(entry);
    });
  });
