  const leaks = [];
  const scan = (dir) => {
    for (const name of readdirSync(dir)) {
      const full = join(dir, name);
      if (statSync(full).isDirectory()) scan(full);
      else {
        const bytes = readFileSync(full).toString('latin1');
        for (const [i, s] of secrets.entries()) if (bytes.includes(s)) leaks.push({ file: full, key: i });
      }
    }
  };
  scan(RUN);
  results.keyLeakScan = { keys: secrets.length, filesWithKey: leaks };
  save();
  log(`key leak scan: ${secrets.length} keys, ${leaks.length} hits`);
  log(`SUMMARY ${JSON.stringify(results.summary)}`);
  clearTimeout(watchdog);
  process.exitCode = results.failures.length ? 1 : 0;
}

