    if (s.child.exitCode === null && !s.record.shutdown) {
      try {
        await stopGateway(s);
      } catch (error) {
        log('stop failure ' + error);
      }
    }
  if (browser) {
    await browser.close().catch((e) => log('browser close error ' + e));
    await sleep(1500);
    const after = await census('after browser close');
    results.browser.closed = true;
    results.browser.ownedProcessesAfterClose = after.rows;
    results.browser.ownedEdgePidsAlive = (results.browser.ownedEdgePids ?? []).filter((pid) => {
      try {
        process.kill(pid, 0);
        return true;
      } catch {
        return false;
      }
    });
  }
  const calls = fixtureStarts();
  results.fixture = {
    starts: calls.length,
    rejected: calls.filter((c) => !ALLOWED_ARGS.includes(c.args.join(' '))).map((c) => c.args),
    distinctArgs: [...new Set(calls.map((c) => c.args.join(' ')))],
  };
  results.finished = new Date().toISOString();
  results.summary = {
    cases: results.cases.length,
    byStatus: results.cases.reduce((acc, c) => ((acc[c.status] = (acc[c.status] ?? 0) + 1), acc), {}),
    failures: results.failures,
  };
  save();
  // Retain redacted gateway logs and the fixture call log.
  for (const s of sessions)
    for (const [kind, path] of [
      ['stdout', s.outLog],
      ['stderr', s.errLog],
    ]) {
      const text = existsSync(path) ? readFileSync(path, 'utf8') : '';
      writeFileSync(join(RUN, `${s.label}-gateway.${kind}.log`), redact(text));
    }
  writeFileSync(join(RUN, 'fixture-calls.jsonl'), existsSync(CALLS) ? readFileSync(CALLS, 'utf8') : '');
  // Synthetic QA key leak scan over every retained file of this run (keys exist only in memory).
  const leaks = [];
  const scan = (dir) => {
    for (const name of readdirSync(dir)) {
      const full = join(dir, name);
      if (statSync(full).isDirectory()) scan(full);
      else {
        const bytes = readFileSync(full).toString('latin1');
        for (const [i, s] of secrets.entries()) if (bytes.includes(s)) leaks.push({ file: full, key: i });
      }
    }
  };
  scan(RUN);
  results.keyLeakScan = { keys: secrets.length, filesWithKey: leaks };
  save();
  log(`key leak scan: ${secrets.length} keys, ${leaks.length} hits`);
  log(`SUMMARY ${JSON.stringify(results.summary)}`);
  clearTimeout(watchdog);
  process.exitCode = results.failures.length ? 1 : 0;
}

