const fs=require("fs"),path=require("path"),crypto=require("crypto");
const root=process.argv[1]; const rows=[];
(function walk(d){for(const e of fs.readdirSync(d,{withFileTypes:true})){const f=path.join(d,e.name);const rel=path.relative(root,f).split(path.sep).join("/");
 if(rel==="provider"||rel==="MANIFEST.sha256.json")continue; if(e.isDirectory())walk(f); else {const b=fs.readFileSync(f);rows.push({path:rel,bytes:b.length,sha256:crypto.createHash("sha256").update(b).digest("hex")});}}})(root);
